baseline.sdl:
# Runtime-authored, credential-free readiness projection for paired clients;
# one atomic JSON snapshot prevents partial reads across registers.
type NodeReadiness @branchable {
    node_did: String @index(unique: true) @immutable
    snapshot_json: String
    updated_at: DateTime @index(direction: DESC)
}

type ChainKeyBinding @branchable
    @index(fields: ["node_did", "binding_id"], unique: true)
    @index(fields: ["node_did", "address"], unique: true) {
    binding_id: String
    node_did: String @index
    address: String @index
    key_backend: String
    attestation: String
    created_at: String
    revoked_at: String
    tags: [String!]
    updated_at: DateTime
}

type PendingChatSubmission {
    request_id: String @index(unique: true)
    payload: String
}

type WorkspaceRoot {
    root_path: String @index(unique: true)
    display_name: String
    enabled: Boolean
    updated_at: DateTime @index(direction: DESC)
}

type CallbackResult @branchable
    @index(fields: ["owner_node_did", "result_id"], unique: true)
    @index(fields: ["owner_node_did", "invocation_id"], unique: true) {
    result_id: String @immutable
    invocation_id: String @index @immutable
    binding_id: String @index @immutable
    owner_node_did: String @index @immutable
    workspace_id: String @index
    work_unit_id: String @index
    caused_by_correlation: String @index @immutable
    created_at: String @index
}

# Local trust-on-first-use binding for authenticated status enrollment;
# deliberately NOT branchable — a pin must never be learned from the network
# it authorizes.
type NetworkAdminPin {
    pin_key: String @index(unique: true) @immutable
    network_id: String @index @immutable
    admin_did: String @index @immutable
    offer_id: String @immutable
    confirmed_at: DateTime @immutable
}

type EnrollmentOperatorNonce {
    nonce_key: String @index(unique: true) @immutable
    admin_did: String @index @immutable
    expires_at: DateTime @index(direction: ASC) @immutable
    consumed_at: DateTime @immutable
}

type FileInventoryPage @branchable @policy(id: "2e14bb0746cf90a5e955db6b9bb5d9098f6aa0776849c8bcb68db4dd1e67ea82", resource: "file_images") {
    request_key: String @index(unique: true) @immutable
    node_did: String @index @immutable
    demand: JSON @immutable
    receipt: JSON @immutable
}

type FileInventoryReply @policy(id: "2e14bb0746cf90a5e955db6b9bb5d9098f6aa0776849c8bcb68db4dd1e67ea82", resource: "file_images") {
  request_key: String @index(unique: true) @immutable
  node_did: String @index @immutable
  demand: JSON @immutable
  reply: JSON @immutable
}

type FileInventoryProgress @policy(id: "2e14bb0746cf90a5e955db6b9bb5d9098f6aa0776849c8bcb68db4dd1e67ea82", resource: "file_images") {
  progress_key: String @index(unique: true) @immutable
  client_did: String @index @immutable
  scope_key: String @index @immutable
  progress: JSON
}

type FileImageHydrationReceipt @policy(id: "2e14bb0746cf90a5e955db6b9bb5d9098f6aa0776849c8bcb68db4dd1e67ea82", resource: "file_images") {
    request_key: String @index(unique: true) @immutable
    node_did: String @index @immutable
    receipt: JSON @immutable
}
